#include <bits/stdc++.h>
using namespace std;

long long floor_div(long long a, long long b) {
    long long q = a / b;
    if ((a % b != 0) && ((a < 0) != (b < 0))) q--;
    return q;
}

int main() {
    int pairs[4][2] = {{7, 2}, {-7, 2}, {7, -2}, {-7, -2}};
    for (auto &p : pairs) {
        int a = p[0], b = p[1];
        cout << a << ' ' << b << ' ' << a / b << ' ' << a % b << ' ' << floor_div(a, b) << '\n';
    }
    int m = 5;
    cout << (-3 % m) << ' ' << ((-3 % m) + m) % m << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1000000007LL;

long long power(long long a, long long e, long long m) {
    long long r = 1;
    a %= m;
    while (e > 0) {
        if (e & 1) r = r * a % m;
        a = a * a % m;
        e >>= 1;
    }
    return r;
}

int main() {
    cout << INT_MAX << ' ' << LLONG_MAX << '\n';
    int a = 100000, b = 100000;
    long long p = 1LL * a * b;
    cout << p << '\n';
    cout << (int)p << '\n';  // int 로 바꾸면 잘려요
    long long x = 1;
    for (int i = 0; i < 100; i++) x = x * 3 % MOD;
    cout << x << ' ' << power(3, 100, MOD) << '\n';
    cout << (17 + 5 - 1) / 5 << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

long long isqrt(long long n) {
    long long r = (long long)sqrt((double)n);
    while (r * r > n) r--;
    while ((r + 1) * (r + 1) <= n) r++;
    return r;
}

int main() {
    cout << boolalpha << (0.1 + 0.2 == 0.3) << '\n';
    cout << (fabs(0.1 + 0.2 - 0.3) < 1e-9) << '\n';
    long long n = 999999999999999999LL;
    cout << (long long)sqrt((double)n) << ' ' << isqrt(n) << '\n';
    long long viaPow = (long long)pow(3, 38);
    long long exact = 1;
    for (int i = 0; i < 38; i++) exact *= 3;
